import csv, json
from datetime import date

AUDIT_DATE = date(2026, 3, 31)
IN = "/app/input"

def parse_date(s):
    if s in (None, "", "none"):
        return None
    y, m, d = s.split("-")
    return date(int(y), int(m), int(d))

# --- load register ---
licences = {}
with open(f"{IN}/licensed_property_register.csv") as f:
    for r in csv.DictReader(f):
        licences[r["license_id"]] = {
            "license_id": r["license_id"],
            "license_type": r["license_type"],
            "covers_distribution": r["covers_distribution"],
            "valid_until": parse_date(r["valid_until"]),
            "max_character_area_pct": None if r["max_character_area_pct"] == "none" else float(r["max_character_area_pct"]),
            "supersedes": None if r["supersedes"] == "none" else r["supersedes"],
        }

# governing map: license_id -> governing license row (following supersession)
def governing(lid):
    # follow chain: a licence is superseded if some other row names it in supersedes
    cur = lid
    # find a row whose supersedes == cur (the successor)
    seen = set()
    while True:
        if cur in seen:
            break
        seen.add(cur)
        succ = None
        for k, v in licences.items():
            if v["supersedes"] == cur and k != cur:
                succ = k
                break
        if succ is None:
            break
        cur = succ
    return licences[cur]

# --- load accounts ---
accounts = {}
with open(f"{IN}/client_accounts.csv") as f:
    for r in csv.DictReader(f):
        accounts[r["account_id"]] = {
            "account_id": r["account_id"],
            "account_type": r["account_type"],
            "master_agreement_covers": r["master_agreement_covers"],  # keep raw
            "agreement_status": r["agreement_status"],
        }

def agreement_covers(acc, distribution):
    if acc["agreement_status"] != "active":
        return False
    cov = acc["master_agreement_covers"]
    if cov == "none":
        return False
    parts = cov.split(";")
    return distribution in parts

# --- §2 licence covers a request for a given license_type and distribution ---
def licence_covers(req_licence_id, license_type, distribution):
    if req_licence_id == "none":
        return False
    if req_licence_id not in licences:
        return False
    gov = governing(req_licence_id)
    if gov["license_type"] != license_type:
        return False
    cov = gov["covers_distribution"]
    if cov == "all":
        pass
    else:
        parts = cov.split(";")
        if distribution not in parts:
            return False
    if gov["valid_until"] < AUDIT_DATE:
        return False
    return True

# --- load requests ---
requests = []
with open(f"{IN}/composite_request_log.csv") as f:
    for r in csv.DictReader(f):
        requests.append(r)

CHAR = "UNLICENSED_CHARACTER_USE"
BG = "THIRD_PARTY_BACKGROUND_UNLICENSED"
CONSENT = "MISSING_MINOR_CONSENT"
COMMERCIAL = "COMMERCIAL_DISTRIBUTION_FLAG"
DISCLOSURE = "ALTERATION_DISCLOSURE_MISSING"

def char_area_pct(req):
    if req["character_px_area"] in (None, "", "none"):
        return None
    return float(req["character_px_area"]) / float(req["canvas_px_area"]) * 100.0

def evaluate(req):
    findings = []
    dist = req["intended_distribution"]
    # §3
    if req["character_property"] != "none":
        cleared = False
        # personal-use allowance
        if dist == "personal_only":
            cleared = True
        else:
            # licence
            lid = req["character_license_id"]
            if licence_covers(lid, "character", dist):
                # prominence cap from governing row
                gov = governing(lid)
                cap = gov["max_character_area_pct"]
                if cap is None:
                    cleared = True
                else:
                    pct = char_area_pct(req)
                    if pct is not None and pct <= cap:
                        cleared = True
                    # else not cleared (exceeds cap)
        if not cleared:
            findings.append(CHAR)
    # §4
    bgs = req["background_source"]
    if bgs == "customer_original":
        pass
    elif bgs == "third_party_unlicensed":
        findings.append(BG)
    elif bgs == "third_party_licensed":
        if not licence_covers(req["background_license_id"], "background", dist):
            findings.append(BG)
    # §5
    if req["subject_is_minor"] == "True":
        ok = True
        if req["minor_consent_type"] == "none":
            ok = False
        v = parse_date(req["minor_consent_valid_until"])
        if v is None or v < AUDIT_DATE:
            ok = False
        # wide enough
        ct = req["minor_consent_type"]
        if ct == "basic":
            if dist not in ("personal_only", "client_internal"):
                ok = False
        elif ct == "publicity":
            pass  # covers every distribution
        else:
            ok = False
        if not ok:
            findings.append(CONSENT)
    # §6
    if dist in ("social_public", "print_for_sale"):
        acc = accounts[req["account_id"]]
        if not agreement_covers(acc, dist):
            findings.append(COMMERCIAL)
    # §7
    if req["alteration_level"] == "substantive" and dist in ("social_public", "print_for_sale"):
        if req["alteration_disclosure_on_file"] != "True":
            findings.append(DISCLOSURE)
    # order by policy finding-names order
    order = [CHAR, BG, CONSENT, COMMERCIAL, DISCLOSURE]
    findings.sort(key=lambda x: order.index(x))
    return findings

# --- run audit ---
audit_rows = []
for req in requests:
    if req["intake_status"] == "withdrawn":
        continue
    fl = evaluate(req)
    audit_rows.append((req["request_id"], req["account_id"], fl))

# per-request verdict
print("=== PER-REQUEST ===")
for rid, acc, fl in audit_rows:
    print(rid, acc, "|".join(fl) if fl else "none")

# counts
request_count = len(audit_rows)
flagged = [r for r in audit_rows if r[2]]
flagged_count = len(flagged)
compliant_count = request_count - flagged_count
finding_total = sum(len(r[2]) for r in audit_rows)

def has_finding(rows, code):
    return sum(1 for r in rows if code in r[2])

character_count = has_finding(audit_rows, CHAR)
background_count = has_finding(audit_rows, BG)
consent_count = has_finding(audit_rows, CONSENT)
commercial_count = has_finding(audit_rows, COMMERCIAL)
disclosure_count = has_finding(audit_rows, DISCLOSURE)

# accounts with audited requests
acc_rows = {}
for rid, acc, fl in audit_rows:
    acc_rows.setdefault(acc, []).append((rid, fl))

account_count = len(acc_rows)

# §8
batch_share = flagged_count / request_count
print("\n=== BATCH SHARE ===", batch_share)

escalation = {}
for acc, rows in acc_rows.items():
    acc_flagged = sum(1 for r in rows if r[1])
    share = acc_flagged / len(rows)
    has_three = any(len(r[1]) >= 3 for r in rows)
    esc = share > batch_share or has_three
    escalation[acc] = (esc, share, acc_flagged, len(rows), has_three)

print("\n=== ACCOUNT ROLLUP ===")
for acc in sorted(acc_rows):
    a = accounts[acc]
    esc, share, af, tot, h3 = escalation[acc]
    print(acc, a["account_type"], tot, af, "ESCALATION_REQUIRED" if esc else "none", f"share={share:.4f} h3={h3}")

escalated_accounts = sum(1 for v in escalation.values() if v[0])

print("\n=== FIGURES ===")
figures = {
    "request_count": request_count,
    "account_count": account_count,
    "flagged_count": flagged_count,
    "compliant_count": compliant_count,
    "finding_total": finding_total,
    "character_count": character_count,
    "background_count": background_count,
    "consent_count": consent_count,
    "commercial_count": commercial_count,
    "disclosure_count": disclosure_count,
    "escalated_accounts": escalated_accounts,
}
for k, v in figures.items():
    print(k, v)

# sanity checks
print("\n=== SANITY ===")
print("flagged+compliant:", flagged_count + compliant_count, "==", request_count)
print("per-finding sum:", character_count+background_count+consent_count+commercial_count+disclosure_count, "==", finding_total)
print("withdrawn:", sum(1 for r in requests if r["intake_status"]=="withdrawn"))

